column77:
={"Transformation information";
byrow(BV3:BV,
lambda(tID,
if(tID="","",
iferror(
let(input_data,transpose(index({Transformations_Comp_cell_procedure,Transformations_Comp_cell_source,Transformations_Colony_counts,Transformations_Colony_sizes,Transformations_Colors,Transformations_Score_notes},
ID_TO_INDEX(tID))),
filtered_input_data,filter(input_data,input_data<>""),
join(" / ",filtered_input_data)
)))))}

